<style nonce="{{ csp_nonce() }}">
.co-overview{display:grid;gap:20px;color:var(--ar-ink)}
.co-hero{padding:28px;display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap;border-top:3px solid var(--ar-accent)}
.co-identity{display:flex;align-items:center;gap:18px;min-width:0;flex:1}
.co-avatar{width:76px;height:76px;flex:0 0 76px;font-size:24px}
.co-heading{min-width:0}.co-heading h2{font-size:clamp(22px,3vw,30px);font-weight:800;line-height:1.2;margin:6px 0 8px;overflow-wrap:anywhere}
.co-eyebrow{font-size:11px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:var(--ar-ink-soft)}
.co-muted{color:var(--ar-ink-soft);font-size:13px;line-height:1.6}
.co-actions{display:flex;flex-wrap:wrap;align-items:center;gap:8px}.co-heading .co-actions{margin-top:12px}
.co-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.co-metric{padding:22px;display:flex;flex-direction:column;gap:8px}
.co-metric-label{display:flex;justify-content:space-between;gap:12px;font-size:13px;font-weight:600}.co-metric-label i{color:var(--ar-accent)}.co-metric strong{font-size:32px;line-height:1.2;font-weight:800;font-variant-numeric:tabular-nums}
.co-columns{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);gap:20px;align-items:start}.co-stack{display:grid;gap:20px;min-width:0}.co-panel{padding:24px;min-width:0}.co-panel h3{font-size:16px;font-weight:700;margin-bottom:18px;display:flex;align-items:center;gap:8px}
.co-facts{margin:0}.co-facts>div{display:flex;justify-content:space-between;gap:20px;padding:12px 0;border-bottom:1px solid var(--ar-line);font-size:13px}.co-facts>div:last-child{border-bottom:0}.co-facts dt{color:var(--ar-ink-soft);flex:1}.co-facts dd{margin:0;text-align:right;font-weight:600;flex:1;min-width:0;overflow-wrap:anywhere}.co-facts small{display:block;font-weight:400;color:var(--ar-ink-soft);margin-top:4px}
.co-divider{border-top:1px solid var(--ar-line);padding-top:16px;margin-top:16px}.co-switch{margin-top:18px;padding:16px;background:var(--ar-bg,#f5f6f8);border-radius:10px;font-size:13px}.co-switch p{margin-bottom:12px;color:var(--ar-ink-soft)}
.co-description{font-size:14px;line-height:1.75;overflow-wrap:anywhere}.co-description p+p{margin-top:12px}.co-description ul{list-style:disc;padding-left:20px}.co-description ol{list-style:decimal;padding-left:20px}.co-description a{text-decoration:underline}
.co-managers{list-style:none;padding:0;margin:0;display:grid;gap:16px}.co-managers li{display:flex;gap:12px;align-items:center;overflow-wrap:anywhere}.co-managers li>div{min-width:0}.co-managers strong{display:block;font-size:13px}.co-managers a{display:block;font-size:12px;margin-top:3px}.co-person{display:grid;place-items:center;width:36px;height:36px;flex-shrink:0;border-radius:50%;background:var(--ar-bg,#f5f6f8);color:var(--ar-ink-soft)}
@media(max-width:1000px){.co-columns{grid-template-columns:1fr}.co-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:520px){.co-hero,.co-panel{padding:18px}.co-avatar{width:52px;height:52px;flex-basis:52px;font-size:18px}.co-identity{gap:12px}.co-metrics{gap:10px}.co-metric{padding:16px}.co-metric strong{font-size:27px}.co-facts>div{gap:12px}.co-hero>.co-actions{width:100%}}
</style>
